import pytest
from target import is_palindrome_dict


class ListNode:
    def __init__(self, val: object = 0, next: object | None = None):
        self.val = val
        self.next = next


def _build_list(values):
    if not values:
        return None
    head = ListNode(values[0])
    current = head
    for val in values[1:]:
        current.next = ListNode(val)
        current = current.next
    return head


class TestIsPalindromeDict:
    def test_empty_list(self):
        assert is_palindrome_dict(None) is True

    def test_single_node(self):
        head = _build_list([1])
        assert is_palindrome_dict(head) is True

    def test_two_identical_nodes(self):
        head = _build_list([1, 1])
        assert is_palindrome_dict(head) is True

    def test_two_different_nodes(self):
        head = _build_list([1, 2])
        assert is_palindrome_dict(head) is False

    def test_palindrome_even_length(self):
        # 1 -> 2 -> 2 -> 1
        head = _build_list([1, 2, 2, 1])
        assert is_palindrome_dict(head) is True

    def test_palindrome_odd_length(self):
        # 1 -> 2 -> 1
        head = _build_list([1, 2, 1])
        assert is_palindrome_dict(head) is True

    def test_non_palindrome(self):
        # 1 -> 2 -> 3
        head = _build_list([1, 2, 3])
        assert is_palindrome_dict(head) is False

    def test_palindrome_strings(self):
        # "r" -> "a" -> "c" -> "e" -> "c" -> "a" -> "r"
        head = _build_list(["r", "a", "c", "e", "c", "a", "r"])
        assert is_palindrome_dict(head) is True

    def test_non_palindrome_strings(self):
        # "h" -> "e" -> "l" -> "l" -> "o"
        head = _build_list(["h", "e", "l", "l", "o"])
        assert is_palindrome_dict(head) is False

    def test_palindrome_with_floats(self):
        # 1.5 -> 2.0 -> 1.5
        head = _build_list([1.5, 2.0, 1.5])
        assert is_palindrome_dict(head) is True

    def test_non_palindrome_with_floats(self):
        # 1.0 -> 2.0 -> 3.0
        head = _build_list([1.0, 2.0, 3.0])
        assert is_palindrome_dict(head) is False

